import codecs, hashlib, itertools, json, sys, unicodedata
assert sys.version_info[:3] == (3,14,7)
assert unicodedata.unidata_version == '16.0.0'
def record(h,row): h.update((json.dumps(row,separators=(',',':'))+'\n').encode())
def attempt(f):
    try:
        value=f()
        return ['ok',list(value) if isinstance(value,bytes) else list(map(ord,value))]
    except (UnicodeEncodeError,UnicodeDecodeError) as e:
        return ['error',list(e.object) if isinstance(e.object,bytes) else list(map(ord,e.object)),e.start,e.end,e.reason]
result={}
for policy in ['strict','ignore','replace']:
    h=hashlib.sha256(); count=0
    for points in itertools.product([65,0xca,0xea,0x304,0x30c,0xd800,0x20000,0x4e2d],repeat=3):
        source=''.join(map(chr,points))
        for split in range(4):
            e=codecs.getincrementalencoder('big5hkscs')(policy)
            row=[attempt(lambda:source.encode('big5hkscs',policy))]
            for chunk,final in [(source[:split],False),(source[split:],False),('',True),('A',True)]:
                row.extend([attempt(lambda:e.encode(chunk,final)),str(e.getstate())])
            record(h,row); count+=1
    result['encode_'+policy]=[count,h.hexdigest()]
    h=hashlib.sha256();count=0
    for first in range(128,256):
        for second in range(256):
            source=bytes([first,second]);d=codecs.getincrementaldecoder('big5hkscs')(policy)
            row=[attempt(lambda:source.decode('big5hkscs',policy))]
            for chunk,final in [(source[:1],False),(source[1:],False),(b'',True),(b'A',True)]:
                row.append(attempt(lambda:d.decode(chunk,final)))
                state=d.getstate();row.append([list(state[0]),state[1]])
            record(h,row);count+=1
    result['decode_'+policy]=[count,h.hexdigest()]
print(json.dumps({'version':sys.version,'unicode':unicodedata.unidata_version,'results':result},indent=2))

